syllableDict = {}

with open(cmuFile, "r", encoding="utf-8", errors="ignore") as f:
    for line in f:
        if line.startswith(";;;") or not line.strip():
            continue

        parts = line.split()
        if len(parts) < 2:
            continue

        word = re.sub(r"\(\d+\)$", "", parts[0]).lower() # 词典可能用 WORD(2) 表示同一个词的另一种读音
        count = sum(sound[-1] in "012" for sound in parts[1:]) # CMU 元音音素以 0 / 1 / 2 标记重音；每个代表一个音节

        if count > 0 and word not in syllableDict:
            syllableDict[word] = count

print("CMU words loaded:", len(syllableDict))

# 若某个词不在 CMU 词典中，用 syllables 库估算音节数
def syllableCount(word):
    if word in syllableDict:
        return syllableDict[word]
    else:
        return max(1, syllables.estimate(word))
